let expirada = false;
try {
  let stampMs = (datos && datos.ultima_actividad) ? (typeof datos.ultima_actividad === 'number' ? datos.ultima_actividad : Date.parse(datos.ultima_actividad)) : NaN;
  if (!Number.isFinite(stampMs) && updatedAt) stampMs = Date.parse(updatedAt);
  if (Number.isFinite(stampMs) && Date.now() - stampMs > 24 * 60 * 60 * 1000) {
    expirada = true;
