let datosSin = {};
if (datos && typeof datos === 'object') { const { historial: _h, ...resto } = datos; datosSin = resto; }
return [{ json: { ...prev, estado, paso, datos: datosSin, historial, historialFull, handoffHilo, handoffMotivo, readErr, expirada } }];

const it = items[0].json;
