    estado = action === 'handoff' ? 'puente' : 'IA';
  }
  datosNuevos.historial = [...(prev.historialFull || []), { u: String(prev.text || '').slice(0, 300), b: String(text || '').slice(0, 300) }].slice(-20);
  datosNuevos.ultima_actividad = new Date().toISOString();
